// Versioned, deterministic screening rules. These are not a medical or FSSAI score.
export const RULE_VERSION='1.0';
export const METRICS=[{key:'sugars',name:'Total sugars',low:5,high:22.5},{key:'saturated',name:'Saturated fat',low:1.5,high:5},{key:'salt',name:'Salt',low:.3,high:1.5},{key:'fat',name:'Total fat',low:3,high:17.5}];
export const number=(v)=>v===null||v===undefined||String(v).trim()===''?null:(Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null);
export function band(value,metric,type='food'){const v=number(value);if(v===null||type!=='food')return 'unknown';return v<=metric.low?'low':v>metric.high?'high':'moderate';}
export function analyze(p,allergies=[]){const metrics=METRICS.map(m=>({...m,value:number(p.nutrition?.[m.key]),level:band(p.nutrition?.[m.key],m,p.type)}));const high=metrics.filter(m=>m.level==='high');const unknown=metrics.filter(m=>m.level==='unknown');const text=[p.ingredients,p.allergens,p.traces].filter(Boolean).join(' ').toLowerCase();const allergyTerms={milk:/\b(milk|whey|casein|butter|cream|cheese|yog[hu]urt|lactose)\b/,peanuts:/\b(groundnuts?|peanuts?)\b/,nuts:/\b(almonds?|cashews?|walnuts?|hazelnuts?|pistachios?|pecans?|tree nuts?|nuts?)\b/,gluten:/\b(wheat|barley|rye|malt|gluten|semolina)\b/,soy:/\b(soy|soya|soybeans?)\b/,eggs:/\b(eggs?|albumen)\b/,sesame:/\b(sesame|tahini)\b/};const matches=allergies.filter(a=>allergyTerms[a]?.test(text));
const notes=[];
if(/\b(sugar|syrup|honey|jaggery|dextrose|glucose|fructose|sucrose)\b/i.test(p.ingredients||''))notes.push({name:'Added-sugar ingredients',tone:'amber',text:'A sugar, syrup, honey or similar sweetener is listed. The label’s total sugars include both naturally occurring and added sugars; we cannot infer the added amount from the ingredient list.'});
if(/\b(palm oil|palm fat|coconut oil|butter|ghee)\b/i.test(p.ingredients||''))notes.push({name:'Sources of saturated fat',tone:'amber',text:'These ingredients can contribute saturated fat. The nutrition panel tells you the amount; the ingredient name alone does not tell you whether the food is high in it.'});
if(/\b(lecithins?|emulsifier|stabili[sz]er|preservative|e\s?\d{3}|ins\s?\d{3})\b/i.test(p.ingredients||''))notes.push({name:'Food additives, explained',tone:'neutral',text:'Additives may help ingredients mix, preserve food or improve texture. Their presence alone is not evidence that a product is unsafe. Check specific sensitivities and the complete label.'});
if(!notes.length)notes.push({name:p.ingredients?'Read the complete label':'Ingredient information is missing',tone:'neutral',text:p.ingredients?'No terms in our limited ingredient dictionary were flagged. This is not a safety or allergy clearance. Ingredient order usually reflects quantities, but exact amounts may be unknown.':'Add the ingredient list before checking ingredient concerns. Missing information cannot be treated as a clean result.'});
let verdict=unknown.length?'More information needed':high.length?'Be portion-aware':metrics.some(m=>m.level==='moderate')?'Some nutrients to watch':'Lower in the nutrients checked';
let explanation=high.length?`High levels of ${high.map(m=>m.name.toLowerCase()).join(', ')} per 100 g under the UK label thresholds used here. Compare similar foods and consider how much you eat.`:unknown.length?'We cannot give a complete nutrition assessment with the available data. Check the packaging and add the missing values.':'No high levels were found for the four nutrients checked. This does not assess overall diet quality, freshness, contaminants or suitability for a medical condition.';
if(p.type!=='food'){verdict='Values shown, rating withheld';explanation='This version applies thresholds only to solid foods per 100 g. Drinks and specialised foods need different criteria. Their values are shown without a traffic-light judgement.';}
if(unknown.length&&high.length)explanation+=' Some values are missing, so this assessment is incomplete.';
return {metrics,high,unknown,matches,notes,verdict,explanation};}
export function validBarcode(s){if(!/^\d+$/.test(s)||![8,12,13,14].includes(s.length))return false;const digits=[...s].map(Number);const check=digits.pop();const sum=digits.reverse().reduce((n,d,i)=>n+d*(i%2===0?3:1),0);return (10-sum%10)%10===check;}
export function fromOFF(p,code){const n=p.nutriments||{};const salt=number(n.salt_100g);const sodium=number(n.sodium_100g);return {id:code,name:p.product_name||p.product_name_en||'Unnamed product',brand:p.brands||'Brand not listed',quantity:p.quantity||'Quantity not listed',ingredients:p.ingredients_text_en||p.ingredients_text||'',allergens:(p.allergens_tags||[]).join(', '),traces:(p.traces_tags||[]).join(', '),type:/beverages|drinks|infant|baby-food|supplements/.test((p.categories_tags||[]).join(' '))?'other':'food',nutrition:{sugars:number(n.sugars_100g),fat:number(n.fat_100g),saturated:number(n['saturated-fat_100g']),salt:salt??(sodium===null?null:sodium*2.5),energy:number(n['energy-kcal_100g']),protein:number(n.proteins_100g),fibre:number(n.fiber_100g)},source:'Open Food Facts',sourceUrl:`https://world.openfoodfacts.org/product/${code}`,date:new Date().toISOString(),serving:30};}
export const DEMOS=[{id:'demo-granola',name:'Almond & honey granola',brand:'THE EVERYDAY PANTRY',quantity:'400 g',ingredients:'Whole grain oats (48%), honey (18%), almonds (12%), sunflower oil, sugar, raisins, salt.',allergens:'almonds, oats',traces:'milk, peanuts',type:'food',nutrition:{sugars:24,fat:16,saturated:2.6,salt:.28,energy:432,protein:10,fibre:7},serving:40,source:'Illustrative demo',demo:true},{id:'demo-oats',name:'Whole grain rolled oats',brand:'THE EVERYDAY PANTRY',quantity:'500 g',ingredients:'Whole grain oats (100%).',allergens:'oats',traces:'wheat',type:'food',nutrition:{sugars:1,fat:7,saturated:1.2,salt:.01,energy:380,protein:13,fibre:10},serving:40,source:'Illustrative demo',demo:true},{id:'demo-crackers',name:'Sea salt crackers',brand:'THE EVERYDAY PANTRY',quantity:'150 g',ingredients:'Wheat flour, sunflower oil, sugar, salt, soy lecithin (emulsifier).',allergens:'wheat, soy',traces:'milk',type:'food',nutrition:{sugars:5,fat:14,saturated:2,salt:1.8,energy:440,protein:8,fibre:3},serving:30,source:'Illustrative demo',demo:true}];
